\set ON_ERROR_STOP on
begin;
create schema campuspass_tests;
create function campuspass_tests.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function campuspass_tests.denied(statement text,expected text,label text) returns void language plpgsql as $$ begin
 begin execute statement; exception when others then if sqlstate=expected then raise notice 'PASS: %',label; return; end if; raise exception 'FAIL: %, expected %, got %: %',label,expected,sqlstate,sqlerrm; end;
 raise exception 'FAIL: %, operation allowed',label; end $$;
create function campuspass_tests.identity(n int) returns void language sql as $$ select set_config('request.jwt.claims',jsonb_build_object('sub',('61000000-0000-4000-8000-'||lpad(n::text,12,'0')),'session_id',('62000000-0000-4000-8000-'||lpad(n::text,12,'0')),'role','authenticated','exp',extract(epoch from clock_timestamp())+3600)::text,true)::void $$;
grant usage on schema campuspass_tests to authenticated,anon;
grant execute on all functions in schema campuspass_tests to authenticated,anon;
insert into auth.users(id,email) select ('61000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'phase6-sql-'||n||'@example.test' from generate_series(1,8) n;
insert into auth.sessions(id,user_id) select ('62000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('61000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,8) n;
insert into public.student_profiles(user_id,display_name,prn,department,academic_year)
 select id,'SQL Student '||row_number() over(),lpad((row_number() over())::text,12,'0'),'Computer Science','Second year' from auth.users where email like 'phase6-sql-%' and email<>'phase6-sql-6@example.test';
insert into public.institutions(id,name,slug) values('63000000-0000-4000-8000-000000000001','Phase Six Institute','phase-six-sql'),('63000000-0000-4000-8000-000000000002','Other Institute','phase-six-other');
select campuspass_private.provision_membership(('61000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
 case when n=5 then '63000000-0000-4000-8000-000000000002'::uuid else '63000000-0000-4000-8000-000000000001'::uuid end,
 case when n in (1,2) then 'organizer'::public.account_role else 'student'::public.account_role end,'active',null,'SQL test operator','Approved isolated test membership') from generate_series(1,6) n;
select campuspass_tests.ok((select count(*) from public.audit_log where action='organizer_granted' and institution_id='63000000-0000-4000-8000-000000000001')=2,'trusted organizer grants are audited');
select campuspass_tests.identity(3);
set local role authenticated;
select campuspass_tests.denied($q$select campuspass_private.provision_membership('61000000-0000-4000-8000-000000000003','63000000-0000-4000-8000-000000000001','organizer','active',null,'Student','Escalating my own privileges')$q$,'42501','private operator provisioning rejects students');
select campuspass_tests.denied($q$update public.institution_memberships set role='organizer'$q$,'42501','direct organizer role escalation denied');
select campuspass_tests.denied($q$select public.save_campus_event(null,null,'Test event','A useful event with a sufficiently detailed description.','Technology','Main hall',now()+interval '2 day',now()+interval '2 day 2 hour',1,'build')$q$,'P1007','ordinary student cannot create an event');
reset role;
select campuspass_tests.identity(1);
set local role authenticated;
select set_config('test.event',(public.save_campus_event(null,null,'Shared Test Event','A useful event with a sufficiently detailed description.','Technology','Main hall',now()+interval '2 day',now()+interval '2 day 2 hour',1,'build')->>'id'),true);
select campuspass_tests.ok((public.get_campus_event(current_setting('test.event')::uuid)->>'status')='draft','organizer creates a private draft');
select campuspass_tests.denied($q$insert into public.events(institution_id,organizer_id) values('63000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000003')$q$,'42501','direct event creation and forged ownership denied');
select public.set_campus_event_status(current_setting('test.event')::uuid,1,'published');
reset role;
select campuspass_tests.identity(2);
set local role authenticated;
select campuspass_tests.denied(format('select public.list_campus_attendees(%L)',current_setting('test.event')),'P1007','another organizer cannot inspect private attendees');
select campuspass_tests.denied(format('select public.set_campus_event_status(%L,2,''cancelled'')',current_setting('test.event')),'P1007','another organizer cannot cancel an event');
reset role;
select campuspass_tests.identity(5);
set local role authenticated;
select campuspass_tests.ok(jsonb_array_length(public.list_campus_events())=0,'cross-institution event discovery isolated');
select campuspass_tests.ok(public.get_campus_event(current_setting('test.event')::uuid) is null,'cross-institution event details hidden');
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.event')),'P1002','cross-institution booking denied');
reset role;
select campuspass_tests.identity(6);
set local role authenticated;
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.event')),'P1003','missing student profile blocks booking');
reset role;
select campuspass_tests.identity(3);
set local role authenticated;
select campuspass_tests.ok(jsonb_array_length(public.list_campus_events())=1,'published event visible to eligible student');
select set_config('test.request',gen_random_uuid()::text,true);
select set_config('test.booking',(public.book_campus_event(current_setting('test.event')::uuid,current_setting('test.request')::uuid)->>'id'),true);
select campuspass_tests.ok((public.book_campus_event(current_setting('test.event')::uuid,current_setting('test.request')::uuid)->>'id')=current_setting('test.booking'),'retry returns stable booking');
select campuspass_tests.ok((public.book_campus_event(current_setting('test.event')::uuid,gen_random_uuid())->>'id')=current_setting('test.booking'),'duplicate request cannot consume another seat');
select campuspass_tests.ok((select count(*) from public.bookings)=1,'student can read exactly their booking');
select campuspass_tests.ok((public.get_campus_event(current_setting('test.event')::uuid)->>'available_seats')::int=0,'server inventory reflects confirmed booking');
select campuspass_tests.denied($q$insert into public.bookings(event_id,student_id) values(gen_random_uuid(),gen_random_uuid())$q$,'42501','direct booking insert and forged identity denied');
reset role;
select campuspass_tests.identity(4);
set local role authenticated;
select campuspass_tests.ok((select count(*) from public.bookings)=0,'another student cannot read private bookings');
select campuspass_tests.denied(format('select public.cancel_campus_booking(%L)',current_setting('test.booking')),'P1008','wrong-user cancellation denied');
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.event')),'P1006','sold-out event rejects another student');
reset role;
select campuspass_tests.identity(3);
set local role authenticated;
select public.cancel_campus_booking(current_setting('test.booking')::uuid);
select public.cancel_campus_booking(current_setting('test.booking')::uuid);
select campuspass_tests.ok((public.get_campus_event(current_setting('test.event')::uuid)->>'available_seats')::int=1,'repeated cancellation frees capacity exactly once');
select campuspass_tests.ok((public.book_campus_event(current_setting('test.event')::uuid,current_setting('test.request')::uuid)->>'status')='cancelled','replaying a cancelled request never rebooks');
select campuspass_tests.ok((public.get_campus_event(current_setting('test.event')::uuid)->>'available_seats')::int=1,'old-request replay leaves inventory unchanged');
select campuspass_tests.ok((public.book_campus_event(current_setting('test.event')::uuid,gen_random_uuid())->>'id')<>current_setting('test.booking'),'explicit rebooking creates a new history record');
reset role;
select campuspass_tests.identity(1);
set local role authenticated;
select campuspass_tests.ok(not (public.list_campus_attendees(current_setting('test.event')::uuid)->0 ?| array['prn','email','student_id']),'attendee response excludes PRN email and user IDs');
select campuspass_tests.denied(format('select public.save_campus_event(%L,1,''Stale event title'',''A useful event with a sufficiently detailed description.'',''Technology'',''Main hall'',now()+interval ''2 day'',now()+interval ''2 day 2 hour'',2,''build'')',current_setting('test.event')),'P1010','stale organizer revision rejected');
select public.save_campus_event(current_setting('test.event')::uuid,2,'Shared Test Event','A useful event with a sufficiently detailed description.','Technology','Main hall',now()+interval '2 day',now()+interval '2 day 2 hour',2,'build');
reset role;
select campuspass_tests.identity(4);
set local role authenticated;
select public.book_campus_event(current_setting('test.event')::uuid,gen_random_uuid());
reset role;
select campuspass_tests.identity(1);
set local role authenticated;
select campuspass_tests.denied(format('select public.save_campus_event(%L,3,''Shared Test Event'',''A useful event with a sufficiently detailed description.'',''Technology'',''Main hall'',now()+interval ''2 day'',now()+interval ''2 day 2 hour'',1,''build'')',current_setting('test.event')),'P1011','capacity cannot shrink below confirmed registrations');
select public.set_campus_event_status(current_setting('test.event')::uuid,3,'cancelled');
select campuspass_tests.ok((public.get_campus_event(current_setting('test.event')::uuid)->>'confirmed_count')::int=0,'event cancellation cancels all confirmed registrations');
reset role;
select campuspass_tests.identity(3);
set local role authenticated;
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.event')),'P1005','cancelled event cannot receive new bookings');
select campuspass_tests.ok(jsonb_array_length(public.list_my_campus_bookings())=2,'cancelled records remain in own history');
reset role;
select campuspass_tests.identity(1);
set local role authenticated;
select set_config('test.past',(public.save_campus_event(null,null,'Time Limited Event','A useful event with a sufficiently detailed description.','Workshops','Main hall',clock_timestamp()+interval '100 milliseconds',clock_timestamp()+interval '1 hour',2,'build')->>'id'),true);
select public.set_campus_event_status(current_setting('test.past')::uuid,1,'published');
reset role;
select campuspass_tests.identity(3);
set local role authenticated;
select set_config('test.pastbooking',(public.book_campus_event(current_setting('test.past')::uuid,gen_random_uuid())->>'id'),true);
select pg_sleep(.15);
select campuspass_tests.denied(format('select public.cancel_campus_booking(%L)',current_setting('test.pastbooking')),'P1004','cancellation cutoff is checked using actual database time');
reset role;
select campuspass_tests.identity(4);
set local role authenticated;
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.past')),'P1004','past event booking denied');
reset role;
-- Time expiry alone used to reserve another student's PRN until their next save.
update public.student_profiles set prn='000000004444' where user_id in ('61000000-0000-4000-8000-000000000007','61000000-0000-4000-8000-000000000008');
select campuspass_private.provision_membership('61000000-0000-4000-8000-000000000007','63000000-0000-4000-8000-000000000001','student','active',clock_timestamp()+interval '50 milliseconds','SQL operator','Approved temporary test membership');
select pg_sleep(.07);
select campuspass_private.provision_membership('61000000-0000-4000-8000-000000000008','63000000-0000-4000-8000-000000000001','student','active',null,'SQL operator','Approved replacement test membership');
select campuspass_tests.ok((select institution_id is null from public.student_profiles where user_id='61000000-0000-4000-8000-000000000007'),'expired PRN association reconciled without old student action');
select campuspass_tests.identity(7);
set local role authenticated;
select campuspass_tests.ok((public.get_campus_access()->>'institution_id') is null,'time-expired membership cannot confer live access');
reset role;
select campuspass_private.provision_membership('61000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001','organizer','revoked',null,'SQL operator','Revoked isolated organizer test access');
select campuspass_tests.identity(1);
set local role authenticated;
select campuspass_tests.denied(format('select public.list_campus_attendees(%L)',current_setting('test.event')),'P1007','revoked organizer loses attendee access');
reset role;
select campuspass_tests.ok(exists(select 1 from public.audit_log where action='organizer_revoked'),'organizer revocation audit is retained');
select campuspass_tests.ok(exists(select 1 from public.audit_log where action='event_published') and exists(select 1 from public.audit_log where action='event_cancelled'),'event publication and cancellation are audited');
select campuspass_tests.identity(3);
update public.institution_memberships set status='revoked',revoked_at=clock_timestamp() where user_id='61000000-0000-4000-8000-000000000003';
set local role authenticated;
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.past')),'P1002','revoked student membership blocks new writes');
select campuspass_tests.denied($q$select * from public.audit_log$q$,'42501','students cannot inspect private operator audits');
select campuspass_tests.denied($q$select * from public.booking_requests$q$,'42501','private idempotency ledger is not exposed');
reset role;
delete from auth.sessions where user_id='61000000-0000-4000-8000-000000000003';
set local role authenticated;
select campuspass_tests.denied($q$select public.list_my_campus_bookings()$q$,'42501','revoked Auth session blocks live RPC reads');
reset role;
select campuspass_tests.identity(4);
update auth.sessions set not_after=clock_timestamp()-interval '1 second' where user_id='61000000-0000-4000-8000-000000000004';
set local role authenticated;
select campuspass_tests.denied(format('select public.book_campus_event(%L,gen_random_uuid())',current_setting('test.past')),'42501','expired backing Auth session blocks new bookings');
select campuspass_tests.ok((select count(*) from public.bookings)=0,'expired backing session cannot read private booking rows');
reset role;
set local role anon;
select campuspass_tests.denied($q$select * from public.bookings$q$,'42501','anonymous private bookings denied');
select campuspass_tests.denied($q$select public.list_campus_events()$q$,'42501','anonymous live RPC denied');
reset role;
rollback;
